const { existsSync } = await import('node:fs');
const imagePath = process.env.IMAGE_PATH;
if (!imagePath) throw new Error('Missing required input: image_path');
if (!existsSync(imagePath)) throw new Error(`Image file not found at ${imagePath}`);
let outputPath = process.env.OUTPUT_PATH;
if (!outputPath) {
  outputPath = imagePath.replace(/\.[^.]+$/, '.pdf');
}
globalThis.imagePath = imagePath;
globalThis.outputPath = outputPath;

const mod = await import('slice2pdf');
const fn = mod.default || mod;
await fn(globalThis.imagePath, globalThis.outputPath);
